              key={plan.id}
              className={`bg-gradient-to-br ${plan.bg} border-l-4 ${plan.border} rounded-xl shadow-lg p-6 flex flex-col justify-between`}
            >
              <div>
                <div className="flex items-center gap-3 mb-3">
