                <p className={`${plan.id === "enterprise" ? "text-base font-medium text-blue-300" : "text-3xl font-bold text-white"} mb-1`}>
                  {plan.price}
                </p>
                <p className="text-sm text-zinc-400 italic mb-4">{plan.suggested}</p>
