import { useCallback } from 'react';

import i18n from '../i18n'; // single source of truth (re-export from i18n.js or i18n/index.js)

export default function useTranslation() {

  const t = useCallback(
    (key, options) => {
      try {
        return i18n.t(key, options);
      } catch {
        return key;
      }
    },
    []
  );

  return t;
}

src/context/LanguageContext.jsx.content:
import { createContext, useState, useEffect, useMemo, useContext } from "react";

export const LanguageContext = createContext();

const langOptions = ["en", "es", "fr", "de", "zh"];

export const LanguageProvider = ({ children }) => {
  const getInitialLang = () => {
    if (typeof window === "undefined") return "en";
    const stored = localStorage.getItem("lang");
    const browserLang = navigator.language.slice(0, 2);
    return langOptions.includes(stored) ? stored : langOptions.includes(browserLang) ? browserLang : "en";
  };

  const [lang, setLang] = useState(getInitialLang);

  useEffect(() => {
    localStorage.setItem("lang", lang);
  }, [lang]);

  const toggleLang = () => {
    const currentIndex = langOptions.indexOf(lang);
    const nextLang = langOptions[(currentIndex + 1) % langOptions.length];
    setLang(nextLang);
  };

  const value = useMemo(() => ({ lang, toggleLang, setLang }), [lang]);

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => useContext(LanguageContext);

