          </Button>
        </form>

        <p className="text-xs text-center text-zinc-500">
          Didn’t get a code?{' '}
          <button
            onClick={() => window.location.reload()}
            className="text-teal-400 hover:underline"
          >
            Resend Code
          </button>
        </p>
      </div>
    </motion.div>
  );
}

